public class FontAwesomeProvider : IIconProvider
{
    public string? GetIconSvg(string name, string? cssClass = null)
    {
        // Return FontAwesome SVG or null to fall back to other providers
        return name switch
        {
            "user" => "<svg class=\"" + cssClass + "\" ...>...</svg>",
            "search" => "<svg class=\"" + cssClass + "\" ...>...</svg>",
            _ => null
        };
    }

    public bool HasIcon(string name) => 
        name is "user" or "search" or "home";
}

// Program.cs
IconRegistry.RegisterProvider(new FontAwesomeProvider());

// Or register individual icons
IconRegistry.Register("custom-logo", "<svg>...</svg>");
